function parse_nested_parens(paren_string){
  return paren_string
    .split(/\s+/)
    .filter(group => group.length > 0)
    .map(group => {
      let depth = 0;
      let maxDepth = 0;

      for (const char of group) {
        if (char === '(') {
          depth++;
          maxDepth = Math.max(maxDepth, depth);
        } else if (char === ')') {
          depth--;
        }
      }

      return maxDepth;
    });
}
