function bell_number(n) {
    n = Number(n);
    if (!Number.isInteger(n) || n < 0) {
        return 0;
    }

    const bell = new Array(n + 1).fill(0);
    bell[0] = 1;

    for (let i = 1; i <= n; i++) {
        let prev = bell[0];
        bell[0] = bell[i - 1];

        for (let j = 1; j <= i; j++) {
            const temp = bell[j];
            bell[j] = bell[j - 1] + prev;
            prev = temp;
        }
    }

    return bell[0];
}
