function factorize(n){
  const factors = [];

  if (n <= 1) {
    return factors;
  }

  for (let d = 2; d * d <= n; d++) {
    while (n % d === 0) {
      factors.push(d);
      n /= d;
    }
  }

  if (n > 1) {
    factors.push(n);
  }

  return factors;
}
