function convert(numbers) {
  function parseComplex(z) {
    var re = 0;
    var im = 0;

    if (Array.isArray(z)) {
      re = Number(z[0]);
      im = Number(z[1]);
      if (!isFinite(re)) re = 0;
      if (!isFinite(im)) im = 0;
    } else if (z && typeof z === "object") {
      re = Number(
        z.re !== undefined ? z.re :
        z.real !== undefined ? z.real :
        z.x !== undefined ? z.x :
        z.a !== undefined ? z.a : 0
      );
      im = Number(
        z.im !== undefined ? z.im :
        z.imag !== undefined ? z.imag :
        z.imaginary !== undefined ? z.imaginary :
        z.y !== undefined ? z.y :
        z.b !== undefined ? z.b : 0
      );
      if (!isFinite(re)) re = 0;
      if (!isFinite(im)) im = 0;
    } else if (typeof z === "string") {
      var s = z.trim().replace(/\s+/g, "").replace(/j/g, "i");

      if (s.indexOf("i") === -1) {
        re = Number(s);
        im = 0;
      } else {
        if (s === "i") s = "1i";
        else if (s === "-i") s = "-1i";
        else if (s === "+i") s = "1i";

        var num = "[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?";
        var m = s.match(new RegExp("^(" + num + ")?(" + num + ")?i$"));

        if (m) {
          if (m[2] !== undefined) {
            re = m[1] !== undefined ? Number(m[1]) : 0;
            im = Number(m[2]);
          } else {
            re = 0;
            im = m[1] !== undefined ? Number(m[1]) : 1;
          }
        } else {
          var imagStr = s.slice(0, -1);
          var splitIndex = -1;

          for (var i = imagStr.length - 1; i > 0; i--) {
            var ch = imagStr.charAt(i);
            if (ch === "+" || ch === "-") {
              if (i > 0 && (imagStr.charAt(i - 1) === "e" || imagStr.charAt(i - 1) === "E")) {
                continue;
              }
              splitIndex = i;
              break;
            }
          }

          var realStr = splitIndex === -1 ? "" : imagStr.slice(0, splitIndex);
          var imagPart = splitIndex === -1 ? imagStr : imagStr.slice(splitIndex);

          re = realStr ? Number(realStr) : 0;

          if (imagPart === "" || imagPart === "+" || imagPart === "-") {
            im = imagPart === "-" ? -1 : 1;
          } else {
            im = Number(imagPart);
          }
        }

        if (!isFinite(re)) re = 0;
        if (!isFinite(im)) im = 0;
      }
    } else {
      re = Number(z);
      im = 0;
      if (!isFinite(re)) re = 0;
    }

    return [re, im];
  }

  function toPolar(z) {
    var parts = parseComplex(z);
    return [Math.hypot(parts[0], parts[1]), Math.atan2(parts[1], parts[0])];
  }

  if (Array.isArray(numbers)) {
    if (numbers.length === 2 && typeof numbers[0] === "number" && typeof numbers[1] === "number") {
      return toPolar(numbers);
    }
    return numbers.map(toPolar);
  }

  return toPolar(numbers);
}
