function max_Product(arr){
  if (!Array.isArray(arr) || arr.length < 2) {
    return null;
  }

  var max1 = -Infinity;
  var max2 = -Infinity;
  var min1 = Infinity;
  var min2 = Infinity;

  for (var i = 0; i < arr.length; i++) {
    var num = arr[i];

    if (num > max1) {
      max2 = max1;
      max1 = num;
    } else if (num > max2) {
