function maxAverageOfPath(cost) {
  const n = cost.length;
  if (n === 0) return 0;

  const dp = new Array(n).fill(0);

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) {
        dp[j] = cost[i][j];
      } else if (i === 0) {
        dp[j] = dp[j - 1] + cost[i][j];
      } else if (j === 0) {
        dp[j] = dp[j] + cost[i][j];
      } else {
        dp[j] = Math.max(dp[j], dp[j - 1]) + cost[i][j];
      }
    }
  }

  return dp[n - 1] / (2 * n - 1);
}
