function find_Index(n) {
    if (n <= 0) return 0;

    function isqrt(x) {
        if (x < 2n) return x;

        let bitLen = 0;
        let t = x;
        while (t > 0n) {
            bitLen++;
            t >>= 1n;
        }

        let y = 1n << BigInt((bitLen + 1) >> 1);
        let z = (y + x / y) >> 1n;

        while (z < y) {
            y = z;
            z = (y + x / y) >> 1n;
        }

        return y;
    }

    const target = 10n ** BigInt(n - 1);
    const disc = 8n * target + 1n;
    const s = isqrt(disc);

    let k = (s * s === disc) ? (s - 1n) / 2n : (s + 1n) / 2n;

    while (k * (k + 1n) / 2n < target) {
        k += 1n;
    }

    while (k > 0n && (k - 1n) * k / 2n >= target) {
        k -= 1n;
    }

    return Number(k);
}
