function lcs_of_three(X, Y, Z){
    if (!X || !Y || !Z) return 0;

    const [A, B, C] = [X, Y, Z].sort((a, b) => b.length - a.length);

    const m = A.length;
    const n = B.length;
    const p = C.length;

    let prev = Array.from({ length: n + 1 }, () => new Array(p + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        const curr = Array.from({ length: n + 1 }, () => new Array(p + 1).fill(0));

        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= p; k++) {
                if (A[i - 1] === B[j - 1] && B[j - 1] === C[k - 1]) {
                    curr[j][k] = prev[j - 1][k - 1] + 1;
                } else {
                    curr[j][k] = Math.max(prev[j][k], curr[j - 1][k], curr[j][k - 1]);
                }
            }
        }

        prev = curr;
    }

    return prev[n][p];
}
