function simplify(x, n) {
  const parseFraction = (s) => {
    const parts = s.split('/');
    return [BigInt(parts[0]), BigInt(parts[1])];
  };

  const gcd = (a, b) => {
    while (b !== BigInt(0)) {
      const t = b;
      b = a % b;
      a = t;
    }
    return a;
  };

  let [numX, denX] = parseFraction(x);
  let [numN, denN] = parseFraction(n);

  let g = gcd(numX, denX);
  numX /= g;
  denX /= g;

  g = gcd(numN, denN);
  numN /= g;
  denN /= g;

  g = gcd(numX, denN);
  numX /= g;
  denN /= g;

  g = gcd(numN, denX);
  numN /= g;
  denX /= g;

  return denX === BigInt(1) && denN === BigInt(1);
}
