function do_algebra(operator, operand) {
    let opIndex = 0;
    let numIndex = 0;

    function parseOperand() {
        return operand[numIndex++];
    }

    function parsePower() {
        let left = parseOperand();

        if (opIndex < operator.length && operator[opIndex] === '**') {
            opIndex++;
            let right = parsePower();
            return Math.pow(left, right);
        }

        return left;
    }

    function parseMulDiv() {
        let left = parsePower();

        while (opIndex < operator.length &&
               (operator[opIndex] === '*' || operator[opIndex] === '//')) {
            const op = operator[opIndex++];
            const right = parsePower();

            if (op === '*') {
                left *= right;
            } else {
                left = Math.floor(left / right);
            }
        }

        return left;
    }

    function parseAddSub() {
        let left = parseMulDiv();

        while (opIndex < operator.length &&
               (operator[opIndex] === '+' || operator[opIndex] === '-')) {
            const op = operator[opIndex++];
            const right = parseMulDiv();

            if (op === '+') {
                left += right;
            } else {
                left -= right;
            }
        }

        return left;
    }

    return parseAddSub();
}
